<?php
namespace Eponymos\Library;

class QuestionRepository {
    private function table($name) { global $wpdb; return $wpdb->prefix . 'eponymos_' . $name; }
    public function all() { global $wpdb; $rows=$wpdb->get_results('SELECT q.*,g.name AS option_group_name FROM '.$this->table('library_questions').' q LEFT JOIN '.$this->table('option_groups').' g ON g.id=q.option_group_id ORDER BY q.updated_at DESC,q.id DESC',ARRAY_A); foreach($rows as &$row){$row['validation']=json_decode($row['validation'],true)?:[];$row['option_group_ids']=array_values(array_filter(array_map('absint',(array)($row['validation']['option_group_ids']??[]))));$row['hide_option_group_titles']=!empty($row['validation']['hide_option_group_titles']);} return $rows; }
    public function find($id) { global $wpdb; $row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.$this->table('library_questions').' WHERE id=%d',absint($id)),ARRAY_A); if($row){$row['validation']=json_decode($row['validation'],true)?:[];$row['option_group_ids']=array_values(array_filter(array_map('absint',(array)($row['validation']['option_group_ids']??[]))));$row['hide_option_group_titles']=!empty($row['validation']['hide_option_group_titles']);} return $row; }
    public function create($data) { global $wpdb; $now=current_time('mysql'); $wpdb->insert($this->table('library_questions'),['label'=>$data['label'],'internal_name'=>$data['internal_name'],'question_key'=>$data['question_key'],'type'=>$data['type'],'required'=>1,'help_text'=>$data['help_text'],'placeholder'=>$data['placeholder'],'validation'=>wp_json_encode($data['validation']),'calculation_eligible'=>!empty($data['calculation_eligible']),'option_group_id'=>absint($data['option_group_id']),'status'=>'active','created_at'=>$now,'updated_at'=>$now],['%s','%s','%s','%s','%d','%s','%s','%s','%d','%d','%s','%s','%s']); return (int)$wpdb->insert_id; }
    public function update($id,$data) { global $wpdb; if(isset($data['validation']))$data['validation']=wp_json_encode($data['validation']); if(array_key_exists('calculation_eligible',$data))$data['calculation_eligible']=(int)(!empty($data['calculation_eligible'])); $data['updated_at']=current_time('mysql'); $formats=array_map(function($k){return in_array($k,['calculation_eligible','option_group_id'],true)?'%d':'%s';},array_keys($data)); return $wpdb->update($this->table('library_questions'),$data,['id'=>absint($id)],$formats,['%d']); }
    public function delete($id) { global $wpdb; return $wpdb->delete($this->table('library_questions'),['id'=>absint($id)],['%d']); }
}
